import ctypes
import os

# Load the libraries in the correct order
libgslcblas_path = "/usr/local/gsl/lib/libgslcblas.so"
libgsl_path = "/usr/local/gsl/lib/libgsl.so"

ctypes.CDLL(libgslcblas_path, mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL(libgsl_path)

# Define the gsl_sf_result structure
class GslSfResult(ctypes.Structure):
    _fields_ = [
        ("val", ctypes.c_double),
        ("err", ctypes.c_double)
    ]

# Define the gsl_sf_beta function
# double gsl_sf_beta(const double x, const double y);
gsl.gsl_sf_beta.argtypes = [ctypes.c_double, ctypes.c_double]
gsl.gsl_sf_beta.restype = ctypes.c_double

def compute_beta(x, y):
    """Compute the Beta function B(x, y) using GSL."""
    if x <= 0 or y <= 0:
        raise ValueError("Inputs x and y must be positive.")
    return gsl.gsl_sf_beta(x, y)

def assert_test():
    """Run assertion tests to validate the implementation."""
    # Test cases
    assert abs(compute_beta(1.0, 1.0) - 1.0) < 1e-6, "Test case 1 failed"
    assert abs(compute_beta(2.0, 2.0) - 0.16666666666666666) < 1e-6, "Test case 2 failed"
    assert abs(compute_beta(0.5, 0.5) - 3.141592653589793) < 1e-6, "Test case 3 failed"

    # Edge case: invalid input
    try:
        compute_beta(-1.0, 2.0)
    except ValueError as e:
        assert str(e) == "Inputs x and y must be positive.", "Edge case 1 failed"

    try:
        compute_beta(2.0, -1.0)
    except ValueError as e:
        assert str(e) == "Inputs x and y must be positive.", "Edge case 2 failed"

    print("All tests passed.")

if __name__ == "__main__":
    assert_test()
